
import Vue from "vue";
import Helpers from "@/helpers";

// Thumbnail that opened the image viewer, so focus can return to it on close
let lastThumb: HTMLElement | null = null;

export default Vue.extend({
  name: "ProjectDetailsOverlay",
  props: {
    visible: Boolean,
    color: String,
    title: String,
    htmlContent: String,
    cover: String,
    tool: String,
  },
  data() {
    return {
      lightbox: {
        open: false,
        images: [] as string[],
        index: 0,
      },
    };
  },
  computed: {
    // Project colour, lifted when it is too dark to read on the panel
    accent(): string {
      return Helpers.readableAccent(this.color || "");
    },
  },
  watch: {
    htmlContent() {
      this.$nextTick(() => this.decorateGallery());
    },
    visible(isOpen: boolean) {
      // Stop the page behind the dialog from scrolling while it is open
      document.body.style.overflow = isOpen ? "hidden" : "";
      if (!isOpen) {
        this.lightbox.open = false;
      }
      if (isOpen) {
        this.$nextTick(() => this.decorateGallery());
        // Move focus into the dialog so keyboard users land on the close control
        this.$nextTick(() => {
          const btn = this.$refs.closeBtn as HTMLElement | undefined;
          if (btn) {
            btn.focus();
          }
        });
      }
    },
  },
  mounted() {
    document.addEventListener("keydown", this.onKeydown);
  },
  beforeDestroy() {
    document.removeEventListener("keydown", this.onKeydown);
    document.body.style.overflow = "";
  },
  methods: {
    onKeydown(e: KeyboardEvent) {
      // While the image viewer is open, keys control it and the project stays open
      if (this.lightbox.open) {
        if (e.key === "Escape") {
          this.closeLightbox();
        } else if (e.key === "ArrowLeft") {
          this.stepLightbox(-1);
        } else if (e.key === "ArrowRight") {
          this.stepLightbox(1);
        }
        return;
      }
      if (this.visible && e.key === "Escape") {
        this.$emit("close");
      }
    },
    onContentClick(e: Event) {
      const target = e.target as HTMLElement;
      if (target.matches("img.pc-screenshot")) {
        this.openLightbox(target as HTMLImageElement);
      }
    },
    onContentKey(e: KeyboardEvent) {
      const target = e.target as HTMLElement;
      if ((e.key === "Enter" || e.key === " ") && target.matches("img.pc-screenshot")) {
        e.preventDefault();
        this.openLightbox(target as HTMLImageElement);
      }
    },
    // All screenshots in the same gallery (same .paragraph block)
    galleryImages(img: HTMLImageElement): HTMLImageElement[] {
      const gallery = img.closest(".paragraph");
      if (!gallery) {
        return [img];
      }
      return Array.from(gallery.querySelectorAll("img.pc-screenshot")) as HTMLImageElement[];
    },
    // Make gallery thumbnails reachable and announceable by keyboard
    decorateGallery() {
      const root = this.$el as HTMLElement;
      root.querySelectorAll(".dialog-content img.pc-screenshot").forEach((node) => {
        const img = node as HTMLImageElement;
        const imgs = this.galleryImages(img);
        img.setAttribute("tabindex", "0");
        img.setAttribute("role", "button");
        img.setAttribute("aria-label", "Open image " + (imgs.indexOf(img) + 1) + " of " + imgs.length);
      });
    },
    openLightbox(img: HTMLImageElement) {
      const imgs = this.galleryImages(img);
      this.showImages(imgs.map((i) => i.getAttribute("src") || ""), Math.max(0, imgs.indexOf(img)), img);
    },
    openCover(e: Event) {
      if (this.cover) {
        this.showImages([this.cover], 0, e.currentTarget as HTMLElement);
      }
    },
    // Shared by gallery thumbnails and the hero cover; focus returns to `returnTo` on close
    showImages(urls: string[], index: number, returnTo: HTMLElement) {
      lastThumb = returnTo;
      this.lightbox.images = urls;
      this.lightbox.index = index;
      this.lightbox.open = true;
      this.$nextTick(() => {
        const btn = this.$refs.lightboxClose as HTMLElement | undefined;
        if (btn) {
          btn.focus();
        }
      });
    },
    closeLightbox() {
      this.lightbox.open = false;
      this.$nextTick(() => {
        if (lastThumb) {
          lastThumb.focus();
        }
      });
    },
    stepLightbox(delta: number) {
      const n = this.lightbox.images.length;
      if (n < 2) {
        return;
      }
      this.lightbox.index = (this.lightbox.index + delta + n) % n;
    },
  },
});
