export interface ProjectDataOptions {
    id: string;
    name: string;
    iconUrl: string;              // used as thumbnail
    html: string;                 // rich description shown in the overlay
    accentColor?: string;         // color of title bar
    tool?: string;                // programming language / tool used in the project
    isHigh?: boolean;             // thumbnail will take 2 rows in the grid view
    isWide?: boolean;             // thumbnail will take 2 cols in the grid view
}

export default class ProjectData {
    id: string;
    name: string;
    iconUrl: string;
    htmlDescription: string;
    tool: string;
    accentColor: string;
    isHigh: boolean;
    isWide: boolean;

    constructor(options: ProjectDataOptions) {
        this.id = options.id;
        this.name = options.name;
        this.iconUrl = options.iconUrl;
        this.htmlDescription = options.html;
        this.accentColor = options.accentColor ?? "#000000";
        this.tool = options.tool ?? "";
        this.isHigh = options.isHigh ?? false;
        this.isWide = options.isWide ?? false;
    }
}